//! Project-cell `.SUBCKT` emission.
//!
//! A placed library cell whose master is a project schematic (no source
//! file) netlists as a self-contained definition: the master's interface
//! ports (in document order) become the `.SUBCKT` port list, its body is
//! generated by the same pipeline as the top level, and nested project
//! cells emit their own definitions leaf-first. The deck that leaves the
//! generator simulates anywhere — no side files, no implicit project state.

use super::*;

/// Read-only access to project cell masters for hierarchical netlisting.
///
/// The workspace owns the design as schematic buffers keyed
/// `"library/cell/view"`; this index exposes the schematic views as
/// netlist masters, case-insensitively.
pub struct HierarchySource<'a> {
    masters: HashMap<String, &'a SchematicState>,
}

impl<'a> HierarchySource<'a> {
    /// Index workspace schematic buffers (keys `"library/cell/view"`).
    pub fn from_buffers(buffers: &'a HashMap<String, SchematicState>) -> Self {
        let mut masters = HashMap::new();
        for (key, schematic) in buffers {
            let mut parts = key.split('/');
            let (Some(library), Some(cell), Some(view)) =
                (parts.next(), parts.next(), parts.next())
            else {
                continue;
            };
            if view.eq_ignore_ascii_case("schematic") {
                masters.insert(Self::key(library, cell), schematic);
            }
        }
        Self { masters }
    }

    /// An empty source — netlisting behaves exactly as before hierarchy
    /// support (every project-cell instance is an unresolved master).
    pub fn empty() -> Self {
        Self {
            masters: HashMap::new(),
        }
    }

    /// Register a master directly (tests, ad-hoc callers).
    pub fn insert(&mut self, library: &str, cell: &str, schematic: &'a SchematicState) {
        self.masters.insert(Self::key(library, cell), schematic);
    }

    /// Look up the schematic master of `library/cell`.
    pub fn master(&self, library: &str, cell: &str) -> Option<&'a SchematicState> {
        self.masters.get(&Self::key(library, cell)).copied()
    }

    fn key(library: &str, cell: &str) -> String {
        format!(
            "{}/{}",
            library.to_ascii_lowercase(),
            cell.to_ascii_lowercase()
        )
    }
}

/// The project cells a schematic instantiates, deduplicated in placement
/// order: bindings without a source file resolve through the hierarchy.
fn project_cells(schematic: &SchematicState) -> Vec<(String, String)> {
    let mut seen = HashSet::new();
    let mut cells = Vec::new();
    for component in &schematic.components {
        if component.kind != ComponentType::CellInstance {
            continue;
        }
        let Some(binding) = component.library_cell.as_ref() else {
            continue;
        };
        if binding.source_path.is_some() {
            continue; // file-backed: handled by .include/.VERILOGA
        }
        let key = format!(
            "{}/{}",
            binding.library.to_ascii_lowercase(),
            binding.cell.to_ascii_lowercase()
        );
        if seen.insert(key) {
            cells.push((binding.library.clone(), binding.cell.clone()));
        }
    }
    cells
}

impl<'a> NetlistGenerator<'a> {
    /// Emit `.SUBCKT` definitions for every project cell this schematic
    /// (transitively) instantiates. Runs after includes, before instances,
    /// so definitions precede use in the emitted deck.
    pub(super) fn generate_subcircuit_definitions(&mut self) {
        let Some(hierarchy) = self.hierarchy else {
            return;
        };
        let needed = project_cells(self.schematic);
        if needed.is_empty() {
            return;
        }

        let mut emitted = HashSet::new();
        let mut stack = Vec::new();
        let mut blocks = Vec::new();
        let mut errors = Vec::new();
        let mut warnings = Vec::new();
        for (library, cell) in needed {
            emit_cell_definition(
                hierarchy,
                &library,
                &cell,
                &mut emitted,
                &mut stack,
                &mut blocks,
                &mut errors,
                &mut warnings,
            );
        }
        self.errors.extend(errors);
        self.warnings.extend(warnings);

        if !blocks.is_empty() {
            self.lines.push("* Project cell definitions".to_string());
            self.lines.extend(blocks);
            self.lines.push(String::new());
        }
    }
}

/// Emit one cell's `.SUBCKT` block (children first), guarding against
/// recursive hierarchies and reporting every defect with cell context.
#[allow(clippy::too_many_arguments)]
fn emit_cell_definition(
    hierarchy: &HierarchySource<'_>,
    library: &str,
    cell: &str,
    emitted: &mut HashSet<String>,
    stack: &mut Vec<String>,
    out: &mut Vec<String>,
    errors: &mut Vec<String>,
    warnings: &mut Vec<String>,
) {
    let key = format!(
        "{}/{}",
        library.to_ascii_lowercase(),
        cell.to_ascii_lowercase()
    );
    if emitted.contains(&key) {
        return;
    }

    let lower_cell = cell.to_ascii_lowercase();
    if stack.contains(&lower_cell) {
        let mut chain = stack.clone();
        chain.push(lower_cell);
        errors.push(format!(
            "Recursive cell hierarchy: {}",
            chain.join(" -> ")
        ));
        return;
    }

    let Some(master) = hierarchy.master(library, cell) else {
        errors.push(format!(
            "Cell master not found in project: {}/{} \u{2039}schematic\u{203A} \
             (open the cell once, or bind a source file)",
            library, cell
        ));
        emitted.insert(key);
        return;
    };

    let ports = master.interface_ports();
    if ports.is_empty() {
        errors.push(format!(
            "Cell '{}/{}' declares no interface ports — place Port components \
             in its schematic to define its pins",
            library, cell
        ));
        emitted.insert(key);
        return;
    }

    // Children first: definitions appear before their first use.
    stack.push(lower_cell.clone());
    for (child_library, child_cell) in project_cells(master) {
        emit_cell_definition(
            hierarchy,
            &child_library,
            &child_cell,
            emitted,
            stack,
            out,
            errors,
            warnings,
        );
    }

    // The master's body runs through the standard pipeline; models and
    // includes stay inside the block, where SPICE scopes them to the cell.
    let mut nested = NetlistGenerator::with_hierarchy(master, hierarchy);
    nested.extract_nets();
    nested.apply_interface_ports();
    nested.apply_net_labels();
    nested.identify_ground();

    // A port tied to ground inside the cell would emit node 0 in the body
    // while the header still declares the port name: the pin would float
    // at every instantiation. Hard error, matching ERC behavior.
    for component in &master.components {
        let Some(spec) = component.port_spec() else {
            continue;
        };
        if let Some((_, terminal)) = component.terminal_positions().into_iter().next()
            && let Some(net) = nested.net_at(terminal)
            && net.spice_name() == "0"
        {
            errors.push(format!(
                "Interface port '{}' of cell '{}/{}' is tied to ground inside \
                 the cell — its pin would float at every instantiation",
                spec.name, library, cell
            ));
        }
    }

    nested.generate_library_view_includes();
    nested.generate_instances();
    nested.generate_models();

    for error in nested.errors() {
        errors.push(format!("in cell {}/{}: {}", library, cell, error));
    }
    for warning in nested.warnings() {
        warnings.push(format!("in cell {}/{}: {}", library, cell, warning));
    }

    let port_list: Vec<&str> = ports.iter().map(|p| p.name.as_str()).collect();
    out.push(String::new());
    out.push(format!(".subckt {} {}", cell, port_list.join(" ")));
    out.extend(
        nested
            .take_lines()
            .into_iter()
            .filter(|line| line != "* Circuit netlist" && !line.is_empty()),
    );
    out.push(format!(".ends {}", cell));

    stack.pop();
    emitted.insert(key);
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::state::{LibraryCellInstance, Point, Wire};

    fn place_port(state: &mut SchematicState, name: &str, pos: Point) {
        let id = state.add_component(ComponentType::Port, pos);
        let component = state
            .components
            .iter_mut()
            .find(|c| c.id == id)
            .expect("port exists");
        component.value = name.to_string();
    }

    fn binding(cell: &str, terminals: &[&str]) -> LibraryCellInstance {
        LibraryCellInstance {
            library: "work".to_owned(),
            cell: cell.to_owned(),
            view: "schematic".to_owned(),
            source_path: None,
            module_name: None,
            terminal_order: terminals.iter().map(|t| t.to_string()).collect(),
        }
    }

    /// `div`: resistor between ports a and b. Port terminals coincide with
    /// the resistor terminals, so connectivity needs no wires.
    fn div_master() -> SchematicState {
        let mut master = SchematicState::default();
        place_port(&mut master, "a", Point::new(20, 0));
        master.add_component(ComponentType::Resistor, Point::new(30, 0));
        place_port(&mut master, "b", Point::new(60, 0));
        master
    }

    /// Testbench instantiating `work/div`: V source into pin 1, pin 2 to
    /// ground.
    fn top_with_instance(terminals: &[&str]) -> SchematicState {
        let mut top = SchematicState::default();
        top.add_library_cell_component(Point::new(100, 0), binding("div", terminals));
        top.add_component(ComponentType::VoltageSource, Point::new(40, 40));
        top.add_component(ComponentType::Ground, Point::new(130, 20));
        top.add_component(ComponentType::Ground, Point::new(40, 70));
        top.wires
            .push(Wire::new(1, vec![Point::new(40, 20), Point::new(40, 0), Point::new(70, 0)]));
        top.wires
            .push(Wire::new(2, vec![Point::new(130, 0), Point::new(130, 10)]));
        top
    }

    #[test]
    fn project_cell_emits_subckt_definition() {
        let master = div_master();
        let mut hierarchy = HierarchySource::empty();
        hierarchy.insert("work", "div", &master);

        let top = top_with_instance(&["a", "b"]);
        let result = generate_netlist_hierarchical(&top, &[], &hierarchy);

        assert!(result.errors.is_empty(), "errors: {:?}", result.errors);
        let text = result.netlist.to_lowercase();
        let def = text.find(".subckt div a b").expect("definition present");
        assert!(text.contains(".ends div"), "netlist:\n{}", result.netlist);
        let body_resistor = text.find("r1 a b").expect("body uses port names");
        let instance = text.find("\nx1 ").expect("X line present");
        assert!(def < instance, "definition must precede use");
        assert!(def < body_resistor && body_resistor < instance);
        // The instance line references the master by cell name.
        let x_line = result
            .netlist
            .lines()
            .find(|l| l.to_lowercase().starts_with("x1 "))
            .expect("x line");
        assert!(x_line.to_lowercase().ends_with(" div"), "got: {x_line}");
    }

    #[test]
    fn empty_binding_resolves_master_ports() {
        let master = div_master();
        let mut hierarchy = HierarchySource::empty();
        hierarchy.insert("work", "div", &master);

        // Legacy placement: terminal_order never populated. The master has
        // two ports and the generic instance has two pins — resolvable.
        let top = top_with_instance(&[]);
        let result = generate_netlist_hierarchical(&top, &[], &hierarchy);
        assert!(result.errors.is_empty(), "errors: {:?}", result.errors);
        assert!(result.netlist.to_lowercase().contains(".subckt div a b"));
    }

    #[test]
    fn nested_cells_emit_leaf_first() {
        let inner = div_master();

        let mut outer = SchematicState::default();
        place_port(&mut outer, "p", Point::new(20, 0));
        place_port(&mut outer, "q", Point::new(60, 0));
        outer.add_library_cell_component(Point::new(120, 0), binding("inner", &["a", "b"]));

        let mut hierarchy = HierarchySource::empty();
        hierarchy.insert("work", "inner", &inner);
        hierarchy.insert("work", "outer", &outer);

        let mut top = SchematicState::default();
        top.add_library_cell_component(Point::new(100, 0), binding("outer", &["p", "q"]));
        let result = generate_netlist_hierarchical(&top, &[], &hierarchy);

        assert!(result.errors.is_empty(), "errors: {:?}", result.errors);
        let text = result.netlist.to_lowercase();
        let inner_def = text.find(".subckt inner").expect("inner def");
        let outer_def = text.find(".subckt outer").expect("outer def");
        assert!(inner_def < outer_def, "leaf definitions come first");
    }

    #[test]
    fn recursive_hierarchy_is_an_error() {
        let mut looper = SchematicState::default();
        place_port(&mut looper, "a", Point::new(20, 0));
        place_port(&mut looper, "b", Point::new(60, 0));
        looper.add_library_cell_component(Point::new(120, 0), binding("loop", &["a", "b"]));

        let mut hierarchy = HierarchySource::empty();
        hierarchy.insert("work", "loop", &looper);

        let mut top = SchematicState::default();
        top.add_library_cell_component(Point::new(100, 0), binding("loop", &["a", "b"]));
        let result = generate_netlist_hierarchical(&top, &[], &hierarchy);

        assert!(
            result
                .errors
                .iter()
                .any(|e| e.contains("Recursive cell hierarchy")),
            "errors: {:?}",
            result.errors
        );
    }

    #[test]
    fn missing_master_is_an_error() {
        let hierarchy = HierarchySource::empty();
        let top = top_with_instance(&["a", "b"]);
        let result = generate_netlist_hierarchical(&top, &[], &hierarchy);
        assert!(
            result
                .errors
                .iter()
                .any(|e| e.contains("master not found in project")),
            "errors: {:?}",
            result.errors
        );
    }

    #[test]
    fn cell_without_ports_is_an_error() {
        let mut master = SchematicState::default();
        master.add_component(ComponentType::Resistor, Point::new(30, 0));

        let mut hierarchy = HierarchySource::empty();
        hierarchy.insert("work", "div", &master);

        let top = top_with_instance(&["a", "b"]);
        let result = generate_netlist_hierarchical(&top, &[], &hierarchy);
        assert!(
            result
                .errors
                .iter()
                .any(|e| e.contains("declares no interface ports")),
            "errors: {:?}",
            result.errors
        );
    }

    #[test]
    fn port_tied_to_ground_is_an_error() {
        let mut master = div_master();
        // Ground terminal coincides with port a's net.
        master.add_component(ComponentType::Ground, Point::new(10, 10));

        let mut hierarchy = HierarchySource::empty();
        hierarchy.insert("work", "div", &master);

        let top = top_with_instance(&["a", "b"]);
        let result = generate_netlist_hierarchical(&top, &[], &hierarchy);
        assert!(
            result
                .errors
                .iter()
                .any(|e| e.contains("tied to ground inside")),
            "errors: {:?}",
            result.errors
        );
    }

    #[test]
    fn stale_binding_is_an_error() {
        let master = div_master(); // two ports
        let mut hierarchy = HierarchySource::empty();
        hierarchy.insert("work", "div", &master);

        let top = top_with_instance(&["a", "b", "c"]); // placed with three
        let result = generate_netlist_hierarchical(&top, &[], &hierarchy);
        assert!(
            result.errors.iter().any(|e| e.contains("is stale")),
            "errors: {:?}",
            result.errors
        );
    }

    #[test]
    fn flat_generation_is_unchanged_without_hierarchy() {
        let top = top_with_instance(&["a", "b"]);
        let result = generate_netlist(&top);
        // No hierarchy source: the project master is unresolvable, which
        // is an error — but no .SUBCKT block is invented.
        assert!(!result.netlist.to_lowercase().contains(".subckt"));
        assert!(!result.errors.is_empty());
    }
}
